/* From Uiverse.io by AnthonyPreite - Tags: green, form, dark, Login, Spotify, duo-ton */
.__UIV_SCOPE__ #form {
  display: grid;
  place-items: center;
  width: 300px;
  height: 472px;
  padding: 25px;
  background-color: #161616;
  box-shadow: 0px 15px 60px #00FF7F;
  outline: 1px solid #2b9962;
  border-radius: 10px;
}

.__UIV_SCOPE__ #form-body {
  position: absolute;
  top: 50%;
  right: 25px;
  left: 25px;
  width: 230px;
  margin: -156px auto 0 auto;
}

.__UIV_SCOPE__ #welcome-lines {
  text-align: center;
  line-height: 1;
}

.__UIV_SCOPE__ #welcome-line-1 {
  color: #00FF7F;
  font-weight: 600;
  font-size: 40px;
}

.__UIV_SCOPE__ #welcome-line-2 {
  color: #ffffff;
  font-size: 18px;
  margin-top: 17px;
}

.__UIV_SCOPE__ #input-area {
  margin-top: 40px;
}

.__UIV_SCOPE__ .form-inp {
  padding: 11px 25px;
  background: transparent;
  border: 1px solid #e3e3e3;
  line-height: 1;
  border-radius: 8px;
}

.__UIV_SCOPE__ .form-inp:focus {
  border: 1px solid #00FF7F;
}

.__UIV_SCOPE__ .form-inp:first-child {
  margin-bottom: 15px;
}

.__UIV_SCOPE__ .form-inp input {
  width: 100%;
  background: none;
  font-size: 13.4px;
  color: #00FF7F;
  border: none;
  padding: 0;
  margin: 0;
}

.__UIV_SCOPE__ .form-inp input:focus {
  outline: none;
}

.__UIV_SCOPE__ #submit-button-cvr {
  margin-top: 20px;
}

.__UIV_SCOPE__ #submit-button {
  display: block;
  width: 100%;
  color: #00FF7F;
  background-color: transparent;
  font-weight: 600;
  font-size: 14px;
  margin: 0;
  padding: 14px 13px 12px 13px;
  border: 0;
  outline: 1px solid #00FF7F;
  border-radius: 8px;
  line-height: 1;
  cursor: pointer;
  transition: all ease-in-out .3s;
}

.__UIV_SCOPE__ #submit-button:hover {
  transition: all ease-in-out .3s;
  background-color: #00FF7F;
  color: #161616;
  cursor: pointer;
}

.__UIV_SCOPE__ #forgot-pass {
  text-align: center;
  margin-top: 10px;
}

.__UIV_SCOPE__ #forgot-pass a {
  color: #868686;
  font-size: 12px;
  text-decoration: none;
}

.__UIV_SCOPE__ #bar {
  position: absolute;
  left: 50%;
  bottom: -50px;
  width: 28px;
  height: 8px;
  margin-left: -33px;
  background-color: #00FF7F;
  border-radius: 10px;
}

.__UIV_SCOPE__ #bar:before,
.__UIV_SCOPE__ #bar:after {
  content: "";
  position: absolute;
  width: 8px;
  height: 8px;
  background-color: #ececec;
  border-radius: 50%;
}

.__UIV_SCOPE__ #bar:before {
  right: -20px;
}

.__UIV_SCOPE__ #bar:after {
  right: -38px;
}
